<script setup>
import {computed,ref,watch} from 'vue'
import {api} from '../api'
import EvidenceText from './EvidenceText.vue'
const props=defineProps({reportId:{type:Number,required:true},section:{type:Object,required:true},wholeBusy:Boolean}),emit=defineEmits(['changed'])
const editing=ref(false),draft=ref(''),baseRevision=ref(0),error=ref(''),success=ref(''),saving=ref(false),showRegenerate=ref(false),instructions=ref(''),history=ref(null)
const sectionBusy=computed(()=>['queued','running'].includes(props.section.generation_status))
const locked=computed(()=>props.wholeBusy||sectionBusy.value||saving.value)
const stale=computed(()=>editing.value&&props.section.revision!==baseRevision.value)
const verification=computed(()=>props.section.verification||{})
const verificationLabel=computed(()=>({verified:'逐句证据核验通过',partial:'存在被拦截句段 / 待评审',insufficient:'证据不足 / 待补充',unverified_manual:'人工草稿未核验',legacy:'历史正文未核验'}[verification.value.state]||'尚未完成核验'))
watch(()=>props.section.revision,()=>{if(!editing.value)draft.value=props.section.content})
function edit(){draft.value=props.section.content;baseRevision.value=props.section.revision;editing.value=true;error.value='';success.value=''}
async function save(){saving.value=true;error.value='';try{await api(`/api/report-tasks/${props.reportId}/sections/${props.section.id}`,{method:'PATCH',body:JSON.stringify({expected_revision:baseRevision.value,content:draft.value})});editing.value=false;success.value='草稿已保存，原修订保留在历史中；人工内容尚未事实核验';emit('changed')}catch(e){error.value=e.message}finally{saving.value=false}}
async function confirm(){saving.value=true;error.value='';try{await api(`/api/report-tasks/${props.reportId}/sections/${props.section.id}`,{method:'PATCH',body:JSON.stringify({expected_revision:props.section.revision,confirmed:!props.section.confirmed})});success.value=props.section.confirmed?'已取消确认':'已确认并保护本节';emit('changed')}catch(e){error.value=e.message}finally{saving.value=false}}
async function regenerate(){saving.value=true;error.value='';try{await api(`/api/report-tasks/${props.reportId}/sections/${props.section.id}/regenerate`,{method:'POST',body:JSON.stringify({expected_revision:props.section.revision,instructions:instructions.value})});showRegenerate.value=false;success.value='仅本节已进入后台队列，旧正文保留到新结果成功提交，其他章节不变';emit('changed')}catch(e){error.value=e.message}finally{saving.value=false}}
async function cancel(){saving.value=true;error.value='';try{await api(`/api/tasks/${props.section.job_id}/cancel`,{method:'POST'});emit('changed')}catch(e){error.value=e.message}finally{saving.value=false}}
async function verify(){saving.value=true;error.value='';try{await api(`/api/report-tasks/${props.reportId}/sections/${props.section.id}/verify`,{method:'POST',body:JSON.stringify({expected_revision:props.section.revision})});success.value='已提交独立核验；保留原正文，结果绑定当前修订，失败不伪造通过';emit('changed')}catch(e){error.value=e.message}finally{saving.value=false}}
async function versions(){if(history.value){history.value=null;return}try{history.value=await api(`/api/report-tasks/${props.reportId}/sections/${props.section.id}/history`)}catch(e){error.value=e.message}}
</script>
<template><div class="section-editor">
 <div class="toolbar"><span class="badge">修订 {{section.revision}}</span><span class="badge" :class="section.confirmed?'green':'amber'">{{section.confirmed?'已确认 / 保护':'未确认'}}</span><span class="badge" :class="verification.state==='verified'?'green':'amber'">{{verificationLabel}}</span><span v-if="sectionBusy" class="badge">本节{{section.generation_status==='queued'?'排队中':'生成或核验中'}} · #{{section.job_id}}</span></div>
 <p class="help">新生成内容须先通过句末引用、独立事实支撑判断、原文逐字引文和数字检查。模型核验可能误判，仍需人工复核；“确认”只保护正文。人工编辑后核验状态立即失效。</p>
 <details v-if="verification.policy" class="verification"><summary>逐句证据核验 · 通过 {{verification.accepted_count}} / 拦截 {{verification.rejected_count}}</summary><p class="help">{{verification.checked_at}} · {{verification.policy}} · 正文SHA256 {{verification.content_sha256}}</p><article v-for="check in verification.checks" :key="check.claim_id"><strong>句段 {{check.claim_id}} · {{check.status==='supported'?'通过':'拦截'}}</strong><p>{{check.reason}} · 引用 {{check.references.join(', ')||'缺失'}}</p><blockquote v-for="(quote,q) in check.quotes||[]" :key="q">[{{quote.reference}}] {{quote.quote}}</blockquote></article></details>
 <div v-if="error" class="error-banner">{{error}}</div><div v-if="success" class="success-banner">{{success}}</div><div v-if="section.generation_error" class="error-banner">本节生成{{section.generation_status}}：{{section.generation_error}}。旧正文已保留。</div>
 <EvidenceText :content="section.content||'本章尚无正文'" :citations="section.citations"/>
 <div v-if="!editing" class="toolbar actions"><button class="secondary-button" :disabled="locked||!!section.confirmed" @click="edit">编辑本节草稿</button><button class="secondary-button" :disabled="locked" @click="confirm">{{section.confirmed?'取消本节确认':'确认并保护本节'}}</button><button class="secondary-button" :disabled="locked||!!section.confirmed" @click="showRegenerate=!showRegenerate">单独重新生成本节</button><button class="secondary-button" :disabled="locked||!!section.confirmed||!section.content" @click="verify">核验当前正文</button><button v-if="sectionBusy" class="danger-button" :disabled="saving" @click="cancel">取消本节生成</button><button class="secondary-button" @click="versions">{{history?'收起修订历史':'查看修订历史'}}</button></div>
 <form v-if="editing" class="draft-form" @submit.prevent="save"><label class="field">本节草稿<textarea v-model="draft" class="textarea draft-text" maxlength="100000" :disabled="saving"/></label><p class="help">沿用本节现有引用编号；人工编辑不自动获得事实校验标记。</p><div v-if="stale" class="error-banner">服务器已有较新修订，本地未保存内容仍保留；保存会被拒绝以避免覆盖。</div><div class="toolbar"><button class="primary-button" :disabled="locked||stale">保存本节草稿</button><button type="button" class="secondary-button" :disabled="saving" @click="editing=false">取消编辑</button></div></form>
 <form v-if="showRegenerate&&!editing" class="draft-form" @submit.prevent="regenerate"><label class="field">本节重新生成要求<textarea v-model="instructions" class="textarea" maxlength="5000" placeholder="例如：仅调整本节表达，保留可追溯引用，不生成其他章节。"/></label><div class="toolbar"><button class="primary-button" :disabled="locked||!!section.confirmed">提交单节后台任务</button><button type="button" class="secondary-button" @click="showRegenerate=false">收起</button></div></form>
 <div v-if="history" class="history"><h4>保留的旧修订 · {{history.length}} 条</h4><details v-for="item in history" :key="item.id"><summary>修订 {{item.revision}} · {{item.reason}} · {{new Date(item.created_at).toLocaleString()}}</summary><EvidenceText :content="item.content" :citations="item.citations"/></details><p v-if="!history.length" class="help">尚未修改，没有旧修订。</p></div>
</div></template>
<style scoped>.section-editor{display:grid;gap:12px;min-width:0;overflow-wrap:anywhere}.help{font-size:12px;color:#6b7f8e;line-height:1.7;margin:0}.verification{padding:12px;border:1px solid #d7e3ea;border-radius:8px}.verification summary{cursor:pointer;font-size:13px;color:#365e77}.verification article{margin-top:12px;font-size:13px}.verification blockquote{margin:8px 0;padding-left:12px;border-left:3px solid #bed3e3;white-space:pre-wrap}.actions{margin-top:4px;flex-wrap:wrap}.draft-form{padding:16px;background:#f2f7fa;border:1px solid #d6e3ec;border-radius:10px}.draft-text{min-height:280px;line-height:1.8}.history details{margin:10px 0;padding:12px;border:1px solid #dde7ee;border-radius:8px}.history summary{cursor:pointer;font-size:12px;color:#365e77}.toolbar{flex-wrap:wrap}</style>
